.page {
  box-sizing: border-box;
  max-width: 1040px;
  margin: 0 auto;
  padding: 0 24px;
}

.hero {
  padding: 96px 0 64px;
  text-align: center;
}

.hero__title {
  display: block;
}

.hero__lead {
  display: block;
  max-width: 640px;
  margin: 20px auto 0;
}

.benefits {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
  padding-bottom: 64px;
}

.benefit {
  padding: 24px;
}

.benefit__title {
  display: block;
  margin-bottom: 8px;
}

.cta {
  display: flex;
